-- Untiered Campus: MCQ tests graded on the server (campus spec §4b, docs/campus-api-contract.md
-- "Module 4b").
--
-- mcq_questions is a global catalogue, like arena_scenarios: it belongs to no college, and its
-- rows are exported from the multiple-choice questions already in the course content
-- (20261114130000_campus_mcq_bank.sql, generated by scripts/export-mcq-bank.mjs). Nothing in it
-- is written for the bank. The answer key lives only here; the API never returns
-- correct_option_id or explanation for an attempt that has not been submitted.
--
-- An assignment gains the kind 'mcq_test' and three columns describing the test. An attempt
-- stores which questions it drew (and the seed it drew them with), the answers once
-- submitted, and the grade the server worked out. Completion and readiness are derived from
-- submitted attempts on read, as for the other kinds; nothing is stored as "completed".
--
-- Conventions as the other campus migrations: every college row carries org_id, children
-- reference parents through (org_id, id) composite keys, RLS is on with no policy for the API
-- roles (the API connects as the owner; PostgREST reads nothing here).
--
-- Additive only, apart from widening the assignment kind check.

create table public.mcq_questions (
  -- The Arena challenge id, e.g. 'mcq-dsa-arrays-1x2y3z': stable, derived from the course, the
  -- chapter and the question text.
  id text primary key check (id ~ '^[a-z0-9-]+$' and length(id) <= 200),
  course_slug text not null check (course_slug ~ '^[a-z0-9-]+$'),
  course_title text not null check (length(btrim(course_title)) > 0),
  chapter_slug text not null check (chapter_slug ~ '^[a-z0-9-]+$'),
  -- A campus topic only where the course truly is one (dsa, java → oops, system-design).
  topic text check (topic in ('dsa', 'dbms', 'os', 'oops', 'cn', 'system_design', 'communication', 'aptitude')),
  prompt text not null check (length(btrim(prompt)) > 0),
  code text,
  -- [{ "id": "a", "text": "…" }, …] in the order the course shows them.
  options jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) between 2 and 6),
  correct_option_id text not null,
  explanation text not null check (length(btrim(explanation)) > 0),
  -- 'retired' when the question left the content; kept so old attempts can still be reviewed.
  status text not null default 'live' check (status in ('live', 'retired')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint mcq_questions_correct_is_an_option
    check (options @> jsonb_build_array(jsonb_build_object('id', correct_option_id)))
);

create index mcq_questions_live_course_idx on public.mcq_questions (course_slug) where status = 'live';

create trigger mcq_questions_set_updated_at
before update on public.mcq_questions
for each row execute function public.set_updated_at();

-- The assignment kind check, widened.
alter table public.assignments drop constraint assignments_kind_check;
alter table public.assignments
  add constraint assignments_kind_check check (kind in ('interview', 'arena_scenarios', 'mcq_test'));

alter table public.assignments
  -- mcq_test: the courses questions are drawn from (mcq_questions.course_slug values, checked
  -- live by the API when written), how many each attempt draws, and an optional time limit.
  add column mcq_course_slugs text[],
  add column mcq_question_count smallint check (mcq_question_count between 5 and 50),
  add column mcq_time_limit_minutes smallint check (mcq_time_limit_minutes between 5 and 120),
  add constraint assignments_mcq_fields check (
    kind <> 'mcq_test'
    or (mcq_course_slugs is not null and cardinality(mcq_course_slugs) between 1 and 10
        and mcq_question_count is not null
        and round_type is null and duration_minutes is null and focus_topic is null and scenario_ids is null)),
  add constraint assignments_mcq_only check (
    kind = 'mcq_test'
    or (mcq_course_slugs is null and mcq_question_count is null and mcq_time_limit_minutes is null));

-- One row per MCQ test a student started from an assignment.
--
-- question_ids are mcq_questions ids in the order drawn, from a random seed stored with the
-- attempt (so the draw can be reproduced). answers is { questionId: optionId } as submitted;
-- correct, total and score are the server's grade. deadline_at is the start plus the time
-- limit, null without one; a submission more than 30 seconds after it is marked late.
--
-- member_id cascades: an attempt is the student's own work and holds their answers, and
-- unlike an interview it spent nothing of the college's, so there is no ledger to keep.
create table public.mcq_attempts (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null,
  assignment_id uuid not null,
  member_id uuid not null,
  seed bigint not null,
  question_ids text[] not null check (cardinality(question_ids) between 1 and 50),
  answers jsonb check (answers is null or jsonb_typeof(answers) = 'object'),
  started_at timestamptz not null default now(),
  deadline_at timestamptz,
  submitted_at timestamptz,
  correct smallint,
  total smallint,
  score smallint check (score between 0 and 100),
  late boolean not null default false,
  unique (org_id, id),
  foreign key (org_id, assignment_id) references public.assignments (org_id, id) on delete cascade,
  foreign key (org_id, member_id) references public.org_members (org_id, id) on delete cascade,
  constraint mcq_attempts_graded check (
    (submitted_at is null) = (answers is null)
    and (submitted_at is null) = (correct is null)
    and (submitted_at is null) = (total is null)
    and (submitted_at is null) = (score is null)),
  constraint mcq_attempts_correct_within_total check (correct is null or correct between 0 and total),
  constraint mcq_attempts_total_is_drawn check (total is null or total = cardinality(question_ids)),
  constraint mcq_attempts_deadline_after_start check (deadline_at is null or deadline_at > started_at),
  constraint mcq_attempts_late_only_submitted check (not late or submitted_at is not null)
);

-- At most one unsubmitted attempt per student per assignment: a second start resumes it.
create unique index mcq_attempts_one_open
  on public.mcq_attempts (org_id, assignment_id, member_id) where submitted_at is null;
create index mcq_attempts_member_idx on public.mcq_attempts (org_id, assignment_id, member_id);

alter table public.mcq_questions enable row level security;
alter table public.mcq_attempts enable row level security;

comment on table public.mcq_questions is
  'The campus MCQ bank: multiple-choice questions exported from the course content, with their answer keys. Global, not per college.';
comment on table public.mcq_attempts is
  'MCQ tests students started from an assignment, the questions each drew, and the server''s grade once submitted.';
comment on column public.mcq_attempts.deadline_at is
  'started_at plus the assignment''s time limit; null when it has none. Submissions over 30 s past it are marked late.';
